            StringBuilder doc=new StringBuilder("{id:"+id+",name:'NoAdMi 规则管理验证',version:1,categories:[{key:1,name:'开屏',enable:true},{key:2,name:'功能',enable:false}],apps:[");
            String[] real={"com.android.settings","io.github.miclean.module"};for(int i=0;i<1502;i++){if(i>0)doc.append(',');String pkg=i<2?real[i]:"noadmi.uninstalled.test"+i;doc.append("{id:'").append(pkg).append("',name:'验证应用").append(i).append("',groups:[{key:1,name:'开屏广告',rules:'[text=\"跳过\"]'},{key:2,name:'功能入口',rules:'[text=\"测试\"]'}]}");}doc.append("]}");
