            click("规则分类  ›");for(int i=0;i<80;i++){boolean[] ready={false};main(()->ready[0]=tag(root(),"rule_category:1")!=null);if(ready[0])break;SystemClock.sleep(50);}main(()->{Switch cat=(Switch)tag(root(),"rule_category:1");check(cat!=null&&cat.isChecked(),"Category missing");cat.performClick();});for(int i=0;i<80&&!Boolean.FALSE.equals(repo.getSources().find(id).getCategories().get(1));i++)SystemClock.sleep(50);check(Boolean.FALSE.equals(repo.getSources().find(id).getCategories().get(1)),"Category not saved");back();
