            click("展示分组 3/3 ▾");dialog("未安装应用",null);dialog("确定",null);awaitCount(2);click("展示分组 2/3 ▾");dialog("系统应用",null);dialog("确定",null);awaitCount(1);click("展示分组 1/3 ▾");dialog("用户应用",null);dialog("确定",null);awaitCount(0);
            click("展示分组 0/3 ▾");for(String group:new String[]{"系统应用","用户应用","未安装应用"})dialog(group,null);dialog("确定",null);awaitCount(1502);
